    [63] = {
      beijing = 1135,
      bganim = 0,
      dialog = 3,
      music = "16_Darkness",
      renwu = "npc",
      sentence = "I'd close some of the rifts, but I wouldn't overextend myself, nor would I turn into some martyr for the cause.",
