    },
    [64] = {
      beijing = 1135,
      dialog = 3,
      music = "16_Darkness",
      renwu = "npc",
      sentence = "Because now, my purpose wasn't to fight—it was to bear witness.",
      next = {65}
    },
    [65] = {
      beijing = 1135,
      dialog = 3,
      music = "16_Darkness",
      renwu = "npc",
      sentence = "The apocalypse unveiled itself like the raising of a great, tattered curtain. I watched the skies split apart with a cruel elegance, while the sea swallowed roads whole, as if nature itself had chosen to reset the stage.",
      next = {66}
    },
    [66] = {
      beijing = 1135,
      dialog = 3,
      music = "16_Darkness",
      renwu = "npc",
      sentence = "Disasters no longer felt novel; they were simply the rhythm of life now. Some people turned into ostriches, hiding their heads in denial. Others scraped together one last fight, clinging to whatever semblance of hope remained...",
      next = {67}
    },
    [67] = {
      beijing = 1135,
      dialog = 3,
      music = "16_Darkness",
      renwu = "npc",
      sentence = "But in the end, the yawning dark rifts would consume them all without distinction.",
      next = {68}
    },
    [68] = {
      beijing = 1135,
      dialog = 3,
      music = "16_Darkness",
      renwu = "npc",
      sentence = "As a witness, I had come to cherish those desperate struggles—they held a rare, fragile beauty.",
      next = {69}
    },
    [69] = {
      beijing = 1135,
      dialog = 3,
      music = "16_Darkness",
      renwu = "npc",
      sentence = "And with each passing day, Shaw's words about the crossroads of history grew heavier in my mind.",
