    [70] = {
      beijing = 1142,
      bganim = 0,
      dialog = 3,
      music = "16_Darkness",
      renwu = "npc",
      sentence = "When Shaw and I finally returned to Loveland City after circling the globe, it was almost unrecognizable.",
      next = {71}
    },
    [71] = {
      beijing = 1142,
      dialog = 3,
      music = "16_Darkness",
      renwu = "npc",
      sentence = "The sandstorms rolled like restless ghosts, blanketing the once-proud skyscrapers, while broken billboards lay scattered like fallen leaves across hollow streets. The city was barely alive—a shadow of its former self.",
      next = {72}
    },
    [72] = {
      beijing = 1142,
